/**
 * Which glyph each keycap wears, mirroring Codex's own keycap catalogue.
 * `null` marks the blank keycaps, which Codex draws as a small empty square.
 */
const KEYCAP_GLYPHS: Record<WorkLouderCodexKeycapId, ((props: GlyphProps) => ReactElement) | null> =
  {
    FAST: LightningOutlineGlyph,
    APPR: CheckCircleGlyph,
    REJ: XCircleGlyph,
    SPLIT: WorktreeGlyph,
    MIC: MicGlyph,
    MIC1: MicGlyph,
    CODEX: CodexGlyph,
    BUG: BugGlyph,
    OAI: OpenaiGlyph,
    TERM: TerminalGlyph,
    DWN: DownloadGlyph,
    DEL: TrashGlyph,
    NEW: ComposeGlyph,
    NAV: PointerOutlineGlyph,
    MAGIC: StarGlyph,
    DIFF: DiffGlyph,
    PLAY: PlayOutlineGlyph,
    GIT: DiffGlyph,
    BRCH: PullRequestDraftGlyph,
    BRANCH: BranchGlyph,
    MRG: PullRequestMergedGlyph,
    PR: PullRequestGlyph,
    PAINT: PaintGlyph,
    LAB: FlaskGlyph,
    PARTY: ConfettiGlyph,
    TIME: ClockGlyph,
    'MIND+': BrainMediumGlyph,
    'MIND-': BrainOutlineGlyph,
    EMPT1: null,
    EMPT2: null,
    EMPT3: null,
    EMPT4: null,
    EMPT5: null,
    SETUP: SettingsGlyph,
    FOLD: FolderPlusGlyph,
    UPL: CloudUploadGlyph,
    APPS: AllProductsGlyph,
    YOLO: null,
    YEET: null,
  };

/** Literal legends Codex silk-screens onto keycaps instead of a glyph. */
const KEYCAP_LEGENDS: Partial<Record<WorkLouderCodexKeycapId, string>> = {
  YOLO: ':yolo:',
  YEET: ':yeet:',
};

export function WorkLouderCodexKeycapGlyph({
  keycapId,
  className,
}: {
  keycapId: WorkLouderCodexKeycapId;
  className?: string;
}) {
  const legend = KEYCAP_LEGENDS[keycapId];
  if (legend) {
    // Codex silk-screens this legend at 0.68rem; text-10 is the nearest step on our ladder.
    return (
      <span className="font-mono text-10 font-medium tracking-[0]" aria-hidden="true">
        {legend}
      </span>
    );
  }

  const Glyph = KEYCAP_GLYPHS[keycapId];
  if (!Glyph) {
    return (
      <span
        aria-hidden="true"
        className="size-3 rounded-sm border border-[var(--border-default)]"
      />
    );
  }

  return <Glyph aria-hidden="true" className={className ?? 'size-5'} />;
}
